def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                            seen.add((ny,nx))
                            stack.append((ny,nx))
            #
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            crop = [row[c0:c1+1] for row in grid[r0:r1+1]]
            objects.append((r0, c0, crop))
    if w >= h:
        objects.sort(key=lambda item: item[1])
        out = [[] for _ in range(max(len(crop) for _, _, crop in objects))]
        for _, _, crop in objects:
            for r in range(len(out)):
                out[r].extend(crop[r] if r < len(crop) else [0] * len(crop[0]))
        return out
    objects.sort(key=lambda item: item[0])
    out = []
    for _, _, crop in objects:
        out.extend(crop)
    return out
